"use client";

import {
  useCallback,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useLocale } from "next-intl";
import type { ColumnDef } from "@tanstack/react-table";
import {
  ArrowDown,
  ArrowUp,
  Columns3,
  Save,
  Share2,
  SlidersHorizontal,
  Trash2,
  X,
} from "lucide-react";
import {
  DataTable,
  defaultTableLabels,
  type DataTableColumnMeta,
  type DataTableLabels,
  type DataTableModeProps,
  type DataTableProps,
} from "@/components/ui/data-table";
import type { TableDensity } from "@/components/ui/table";
import { Alert } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { MultiSelect } from "@/components/ui/multi-select";
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Select } from "@/components/ui/select";
import {
  isDataFilter,
  matchesDataFilter,
  normalizeDataTableColumnState,
  normalizeDataTableQuery,
  serializeDataTableQuery,
  type DataFilter,
  type DataFilterScalar,
  type DataTableColumnState,
  type DataTableQuery,
} from "@/lib/data-query";
import { cn } from "@/lib/utils";

export type DataWorkbenchValue = {
  query: DataTableQuery;
  columns?: Partial<DataTableColumnState>;
  density?: TableDensity;
};

export type DataWorkbenchSavedView = {
  id: string;
  name: string;
  value: DataWorkbenchValue;
};

export type DataWorkbenchFilterOption = {
  value: DataFilterScalar;
  label: string;
};

type FilterFieldBase = { id: string; label: string; placeholder?: string };

/** All fields are AND conditions. A multi-select matches any selected option within its field. */
export type DataWorkbenchFilterField<T> = FilterFieldBase &
  (
    | {
        type: "text";
        operator?: "contains" | "startsWith";
        getValue?: (row: T) => string | null | undefined;
      }
    | {
        type: "select" | "multi-select";
        options: readonly DataWorkbenchFilterOption[];
        getValue?: (row: T) => DataFilterScalar | undefined;
      }
    | { type: "number-range"; getValue?: (row: T) => number | null | undefined }
    | {
        type: "date-range";
        getValue?: (row: T) => string | Date | null | undefined;
      }
  );

const englishLabels = {
  toolbar: "Table controls",
  savedViews: "Saved views",
  allRecords: "Current view",
  filters: "Filters",
  filterDescription: "Records must match every condition.",
  activeFilters: "Active filters",
  search: "Search",
  clearFilters: "Clear filters",
  removeFilter: "Remove filter",
  anyValue: "Any value",
  minimum: "Minimum",
  maximum: "Maximum",
  fromDate: "From date",
  toDate: "To date",
  invalidRange: "The end of the range must not precede its start.",
  columns: "Configure columns",
  columnDescription:
    "Choose visibility, order, pinned columns and widths for this view.",
  density: "Density",
  comfortable: "Comfortable",
  compact: "Compact",
  showColumn: "Show column",
  moveEarlier: "Move earlier",
  moveLater: "Move later",
  pin: "Pin",
  unpinned: "Not pinned",
  pinLeft: "Left",
  pinRight: "Right",
  width: "Width in pixels",
  saveView: "Save view",
  viewName: "View name",
  save: "Save",
  saveNewView: "Save as new",
  cancel: "Cancel",
  deleteView: "Delete view",
  shareView: "Share view",
  actionError: "Could not complete the view action",
  emptyOptions: "No options found",
  removeOption: "Remove",
  keyboardHint: "Press Backspace or Delete to remove",
  emptyValue: "Empty",
  hasValue: "Has a value",
  trueValue: "Yes",
  falseValue: "No",
  not: "Not",
  startsWith: "Starts with",
  activeCondition: "Active condition",
};
export type DataWorkbenchLabels = {
  [Key in keyof typeof englishLabels]: string;
};
const spanishLabels: DataWorkbenchLabels = {
  toolbar: "Controles de la tabla",
  savedViews: "Vistas guardadas",
  allRecords: "Vista actual",
  filters: "Filtros",
  filterDescription: "Los registros deben cumplir todas las condiciones.",
  activeFilters: "Filtros activos",
  search: "Búsqueda",
  clearFilters: "Limpiar filtros",
  removeFilter: "Quitar filtro",
  anyValue: "Cualquier valor",
  minimum: "Mínimo",
  maximum: "Máximo",
  fromDate: "Desde",
  toDate: "Hasta",
  invalidRange: "El final del rango no puede ser anterior al inicio.",
  columns: "Configurar columnas",
  columnDescription:
    "Elige visibilidad, orden, columnas fijas y anchos para esta vista.",
  density: "Densidad",
  comfortable: "Cómoda",
  compact: "Compacta",
  showColumn: "Mostrar columna",
  moveEarlier: "Mover antes",
  moveLater: "Mover después",
  pin: "Fijar",
  unpinned: "Sin fijar",
  pinLeft: "Izquierda",
  pinRight: "Derecha",
  width: "Ancho en píxeles",
  saveView: "Guardar vista",
  viewName: "Nombre de la vista",
  save: "Guardar",
  saveNewView: "Guardar como nueva",
  cancel: "Cancelar",
  deleteView: "Eliminar vista",
  shareView: "Compartir vista",
  actionError: "No se pudo completar la acción de la vista",
  emptyOptions: "No se encontraron opciones",
  removeOption: "Quitar",
  keyboardHint: "Pulsa Retroceso o Suprimir para quitar",
  emptyValue: "Vacío",
  hasValue: "Tiene un valor",
  trueValue: "Sí",
  falseValue: "No",
  not: "No",
  startsWith: "Empieza por",
  activeCondition: "Condición activa",
};

const spanishTableLabels: Required<DataTableLabels> = {
  search: "Buscar registros…",
  empty: "No se encontraron registros",
  emptyDescription: "Prueba otra búsqueda o limpia los filtros.",
  previous: "Página anterior",
  next: "Página siguiente",
  selectAll: "Seleccionar esta página",
  selectRow: "Seleccionar fila",
  selected: "seleccionados",
  page: "Página",
  of: "de",
  rows: "registros",
  clear: "Limpiar búsqueda",
  error: "No se pudieron cargar los registros",
  retry: "Reintentar",
  loading: "Cargando registros",
  columns: "Columnas",
  clearSelection: "Limpiar selección",
  rowsPerPage: "Registros por página",
};

export type DataWorkbenchProps<T extends { id: string }> = Omit<
  DataTableProps<T>,
  | "query"
  | "onQueryChange"
  | "columnState"
  | "onColumnStateChange"
  | "density"
  | "labels"
  | "mode"
  | "rowCount"
> &
  DataTableModeProps & {
    value: DataWorkbenchValue;
    onValueChange: (value: DataWorkbenchValue) => void;
    onQueryChange?: (query: DataTableQuery) => void;
    filterFields?: readonly DataWorkbenchFilterField<T>[];
    savedViews?: readonly DataWorkbenchSavedView[];
    activeViewId?: string;
    onActiveViewChange?: (id: string | undefined) => void;
    onSaveView?: (view: DataWorkbenchSavedView) => void | Promise<void>;
    onDeleteView?: (id: string) => void | Promise<void>;
    onShareView?: (
      value: DataWorkbenchValue,
      view?: DataWorkbenchSavedView,
    ) => void | Promise<void>;
    columnConfig?: boolean;
    labels?: Partial<DataWorkbenchLabels>;
    tableLabels?: Partial<DataTableLabels>;
  };

type ResolvedValue = {
  query: DataTableQuery;
  columns: DataTableColumnState;
  density: TableDensity;
};
const emptyItems = [] as const;

function resolveValue(value: DataWorkbenchValue): ResolvedValue {
  return {
    query: normalizeDataTableQuery(value.query),
    columns: normalizeDataTableColumnState(value.columns),
    density: value.density === "compact" ? "compact" : "comfortable",
  };
}

function columnId<T>(column: ColumnDef<T>): string | undefined {
  if (column.id) return column.id;
  if ("accessorKey" in column)
    return String(column.accessorKey).replaceAll(".", "_");
  return typeof column.header === "string" ? column.header : undefined;
}

function leafColumns<T>(columns: ColumnDef<T>[]) {
  return columns.flatMap(
    (
      column,
    ): {
      id: string;
      label: string;
      definition: ColumnDef<T>;
      accessor: boolean;
    }[] => {
      if ("columns" in column && column.columns)
        return leafColumns(column.columns);
      const id = columnId(column);
      if (!id) return [];
      const meta = column.meta as DataTableColumnMeta | undefined;
      return [
        {
          id,
          label:
            meta?.label ??
            (typeof column.header === "string" ? column.header : id),
          definition: column,
          accessor: "accessorKey" in column || "accessorFn" in column,
        },
      ];
    },
  );
}

function scalarLabel<T>(
  value: DataFilterScalar,
  field: DataWorkbenchFilterField<T> | undefined,
  labels: DataWorkbenchLabels,
) {
  if (field && (field.type === "select" || field.type === "multi-select")) {
    const option = field.options.find((option) =>
      Object.is(option.value, value),
    );
    if (option) return option.label;
  }
  return value === null
    ? labels.emptyValue
    : value === true
      ? labels.trueValue
      : value === false
        ? labels.falseValue
        : String(value);
}

function filterLabel<T>(
  value: unknown,
  field: DataWorkbenchFilterField<T> | undefined,
  labels: DataWorkbenchLabels,
): string {
  const format = (value: DataFilterScalar) => scalarLabel(value, field, labels);
  if (!isDataFilter(value)) {
    if (Array.isArray(value))
      return value.map((item) => format(item)).join(", ");
    return typeof value === "string" ||
      typeof value === "number" ||
      typeof value === "boolean" ||
      value === null
      ? format(value)
      : labels.activeCondition;
  }
  switch (value.operator) {
    case "contains":
    case "equals":
      return format(value.value);
    case "startsWith":
      return `${labels.startsWith} ${value.value}`;
    case "notEquals":
      return `≠ ${format(value.value)}`;
    case "in":
      return value.value.map(format).join(", ");
    case "notIn":
      return `${labels.not}: ${value.value.map(format).join(", ")}`;
    case "between":
    case "dateBetween":
      return `${value.value[0] ?? "…"} – ${value.value[1] ?? "…"}`;
    case "isEmpty":
      return labels.emptyValue;
    case "isNotEmpty":
      return labels.hasValue;
    case "gt":
      return `> ${value.value}`;
    case "gte":
      return `≥ ${value.value}`;
    case "lt":
      return `< ${value.value}`;
    case "lte":
      return `≤ ${value.value}`;
  }
}

function FilterControl<T>({
  field,
  value,
  onChange,
  labels,
}: {
  field: DataWorkbenchFilterField<T>;
  value: unknown;
  onChange: (value: DataFilter | undefined) => void;
  labels: DataWorkbenchLabels;
}) {
  const id = useId();
  if (field.type === "text") {
    const text =
      isDataFilter(value) &&
      (value.operator === "contains" || value.operator === "startsWith")
        ? value.value
        : typeof value === "string"
          ? value
          : "";
    return (
      <label className="grid gap-2 text-xs font-medium">
        {field.label}
        <Input
          value={text}
          placeholder={field.placeholder}
          onChange={(event) =>
            onChange({
              operator: field.operator ?? "contains",
              value: event.target.value,
            })
          }
        />
      </label>
    );
  }
  if (field.type === "select" || field.type === "multi-select") {
    const options = field.options.map((option) => ({
      value: JSON.stringify(option.value),
      label: option.label,
    }));
    if (field.type === "select") {
      const selected =
        isDataFilter(value) && value.operator === "equals"
          ? value.value
          : value;
      const code =
        options.find((option, index) =>
          Object.is(field.options[index].value, selected),
        )?.value ?? "";
      return (
        <Select
          label={field.label}
          options={[{ value: "", label: labels.anyValue }, ...options]}
          value={code}
          onValueChange={(code) => {
            const option = field.options.find(
              (option) => JSON.stringify(option.value) === code,
            );
            onChange(
              option ? { operator: "equals", value: option.value } : undefined,
            );
          }}
        />
      );
    }
    const selected =
      isDataFilter(value) && value.operator === "in"
        ? value.value
        : Array.isArray(value)
          ? value
          : [];
    return (
      <div className="grid gap-2">
        <span className="text-xs font-medium">{field.label}</span>
        <MultiSelect
          label={field.label}
          options={options}
          value={options
            .filter((option, index) =>
              selected.some((item) =>
                Object.is(item, field.options[index].value),
              ),
            )
            .map((option) => option.value)}
          placeholder={field.placeholder ?? labels.anyValue}
          emptyLabel={labels.emptyOptions}
          removeLabel={labels.removeOption}
          keyboardHint={labels.keyboardHint}
          onValueChange={(codes) =>
            onChange({
              operator: "in",
              value: field.options
                .filter((option) =>
                  codes.includes(JSON.stringify(option.value)),
                )
                .map((option) => option.value),
            })
          }
        />
      </div>
    );
  }
  const date = field.type === "date-range";
  let range: [number | string | null, number | string | null] = [null, null];
  if (isDataFilter(value)) {
    if (date && value.operator === "dateBetween") range = value.value;
    if (!date && value.operator === "between") range = value.value;
  }
  const invalid = range[0] !== null && range[1] !== null && range[0] > range[1];
  return (
    <fieldset className="grid gap-2">
      <legend className="mb-2 text-xs font-medium">{field.label}</legend>
      <div className="grid grid-cols-2 gap-2">
        {[0, 1].map((index) => (
          <Input
            key={index}
            type={date ? "date" : "number"}
            step={date ? undefined : "any"}
            aria-label={`${field.label}: ${date ? (index ? labels.toDate : labels.fromDate) : index ? labels.maximum : labels.minimum}`}
            aria-invalid={invalid || undefined}
            aria-describedby={invalid ? id : undefined}
            placeholder={index ? labels.maximum : labels.minimum}
            value={range[index] ?? ""}
            onChange={(event) => {
              const input = event.target.value;
              if (date) {
                const next: [string | null, string | null] = [
                  range[0] as string | null,
                  range[1] as string | null,
                ];
                next[index] = input || null;
                onChange({ operator: "dateBetween", value: next });
              } else {
                const number = input === "" ? null : Number(input);
                if (number !== null && !Number.isFinite(number)) return;
                const next: [number | null, number | null] = [
                  range[0] as number | null,
                  range[1] as number | null,
                ];
                next[index] = number;
                onChange({ operator: "between", value: next });
              }
            }}
          />
        ))}
      </div>
      {invalid && (
        <p
          id={id}
          role="status"
          className="text-xs text-destructive-foreground"
        >
          {labels.invalidRange}
        </p>
      )}
    </fieldset>
  );
}

/** Controlled data UI; fetching, URL state and saved-view persistence belong to the caller. */
export function DataWorkbench<T extends { id: string }>(
  props: DataWorkbenchProps<T>,
) {
  const {
    value,
    onValueChange,
    onQueryChange,
    columns,
    filterFields = emptyItems,
    savedViews = emptyItems,
    activeViewId,
    onActiveViewChange,
    onSaveView,
    onDeleteView,
    onShareView,
    columnConfig = true,
    labels: labelOverrides,
    tableLabels: tableLabelOverrides,
    className,
    ...tableProps
  } = props;
  const locale = useLocale();
  const id = useId();
  const labels = useMemo(
    () => ({
      ...(locale.startsWith("es") ? spanishLabels : englishLabels),
      ...labelOverrides,
    }),
    [locale, labelOverrides],
  );
  const tableLabels = useMemo(
    () => ({
      ...(locale.startsWith("es") ? spanishTableLabels : defaultTableLabels),
      ...tableLabelOverrides,
    }),
    [locale, tableLabelOverrides],
  );
  const resolved = useMemo(() => resolveValue(value), [value]);
  const current = useRef(resolved);
  useLayoutEffect(() => {
    current.current = resolved;
  });
  const [internalActiveId, setInternalActiveId] = useState<string>();
  const [saveOpen, setSaveOpen] = useState(false);
  const [viewName, setViewName] = useState("");
  const [pendingAction, setPendingAction] = useState<
    "save" | "delete" | "share"
  >();
  const [actionError, setActionError] = useState<string>();
  const activeViewControlled = Object.hasOwn(props, "activeViewId");
  const activeView = savedViews.find(
    (view) =>
      view.id === (activeViewControlled ? activeViewId : internalActiveId),
  );
  const setActiveView = (id: string | undefined) => {
    if (!activeViewControlled) setInternalActiveId(id);
    onActiveViewChange?.(id);
  };
  const emit = useCallback(
    (update: (previous: ResolvedValue) => DataWorkbenchValue) => {
      const previous = current.current;
      const next = resolveValue(update(previous));
      const queryChanged =
        serializeDataTableQuery(previous.query) !==
        serializeDataTableQuery(next.query);
      if (
        !queryChanged &&
        JSON.stringify(previous.columns) === JSON.stringify(next.columns) &&
        previous.density === next.density
      )
        return;
      current.current = next;
      onValueChange(next);
      if (queryChanged) onQueryChange?.(next.query);
    },
    [onValueChange, onQueryChange],
  );
  const updateColumns = (
    update: (previous: DataTableColumnState) => DataTableColumnState,
  ) => emit((previous) => ({ ...previous, columns: update(previous.columns) }));
  const setFilter = (id: string, filter: DataFilter | undefined) =>
    emit((previous) => ({
      ...previous,
      query: {
        ...previous.query,
        filters: [
          ...previous.query.filters.filter((filter) => filter.id !== id),
          ...(filter ? [{ id, value: filter }] : []),
        ],
        pagination: { ...previous.query.pagination, pageIndex: 0 },
      },
    }));
  const configuredColumns = useMemo(() => {
    const fields = new Map(filterFields.map((field) => [field.id, field]));
    const configure = (definitions: ColumnDef<T>[]): ColumnDef<T>[] =>
      definitions.map((column) => {
        if ("columns" in column && column.columns)
          return { ...column, columns: configure(column.columns) };
        const id = columnId(column),
          field = id ? fields.get(id) : undefined;
        return field
          ? {
              ...column,
              filterFn: (row, columnId, filter) =>
                matchesDataFilter(
                  field.getValue
                    ? field.getValue(row.original)
                    : row.getValue(columnId),
                  filter,
                ),
            }
          : column;
      });
    return configure(columns);
  }, [columns, filterFields]);
  const leaves = useMemo(() => leafColumns(columns), [columns]);
  const orderedLeaves = useMemo(() => {
    const byId = new Map(leaves.map((column) => [column.id, column]));
    const ordered = resolved.columns.order.flatMap((id) =>
      byId.has(id) ? [byId.get(id)!] : [],
    );
    return [
      ...ordered,
      ...leaves.filter((column) => !resolved.columns.order.includes(column.id)),
    ];
  }, [leaves, resolved.columns.order]);
  const visibleAccessors = leaves.filter(
    (column) =>
      column.accessor && resolved.columns.visibility[column.id] !== false,
  ).length;
  const chipCount =
    resolved.query.filters.length + (resolved.query.search ? 1 : 0);
  const clearFilters = () =>
    emit((previous) => ({
      ...previous,
      query: {
        ...previous.query,
        search: "",
        filters: [],
        pagination: { ...previous.query.pagination, pageIndex: 0 },
      },
    }));
  const runAction = async (
    kind: "save" | "delete" | "share",
    action: () => void | Promise<void>,
  ) => {
    setPendingAction(kind);
    setActionError(undefined);
    try {
      await action();
    } catch (error) {
      setActionError(
        error instanceof Error ? error.message : labels.actionError,
      );
    } finally {
      setPendingAction(undefined);
    }
  };
  const saveView = (asNew: boolean) => {
    if (!onSaveView || !viewName.trim()) return;
    void runAction("save", async () => {
      const next: DataWorkbenchSavedView = {
        id:
          !asNew && activeView
            ? activeView.id
            : (globalThis.crypto?.randomUUID?.() ?? `${id}-${Date.now()}`),
        name: viewName.trim(),
        value: resolveValue(current.current),
      };
      await onSaveView(next);
      setActiveView(next.id);
      setSaveOpen(false);
    });
  };
  return (
    <div
      data-slot="data-workbench"
      className={cn("min-w-0 space-y-3", className)}
    >
      <div
        role="group"
        aria-label={labels.toolbar}
        className="flex flex-wrap items-center gap-2 rounded-xl border border-border bg-surface/55 p-3"
      >
        {(savedViews.length > 0 || onSaveView) && (
          <Select
            aria-label={labels.savedViews}
            className="w-full sm:w-48"
            options={[
              { value: "", label: labels.allRecords },
              ...savedViews.map((view) => ({
                value: view.id,
                label: view.name,
              })),
            ]}
            value={activeView?.id ?? ""}
            onValueChange={(id) => {
              const view = savedViews.find((view) => view.id === id);
              if (view) emit(() => view.value);
              setActiveView(view?.id);
            }}
          />
        )}
        {filterFields.length > 0 && (
          <Popover>
            <PopoverTrigger
              render={<Button type="button" variant="outline" size="sm" />}
            >
              <SlidersHorizontal aria-hidden="true" />
              {labels.filters}
              {resolved.query.filters.length > 0 && (
                <span className="rounded bg-accent px-1.5 text-accent-foreground tabular-nums">
                  {resolved.query.filters.length}
                </span>
              )}
            </PopoverTrigger>
            <PopoverContent
              align="start"
              className="max-h-[70dvh] w-[min(24rem,calc(100vw-2rem))] overflow-y-auto"
            >
              <PopoverTitle className="text-sm font-semibold">
                {labels.filters}
              </PopoverTitle>
              <PopoverDescription className="mt-1 text-xs leading-5 text-muted-foreground">
                {labels.filterDescription}
              </PopoverDescription>
              <div className="mt-4 grid gap-4">
                {filterFields.map((field) => (
                  <FilterControl
                    key={field.id}
                    field={field}
                    value={
                      resolved.query.filters.find(
                        (filter) => filter.id === field.id,
                      )?.value
                    }
                    labels={labels}
                    onChange={(value) => setFilter(field.id, value)}
                  />
                ))}
              </div>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="mt-4"
                disabled={!chipCount}
                onClick={clearFilters}
              >
                {labels.clearFilters}
              </Button>
            </PopoverContent>
          </Popover>
        )}
        {columnConfig && (
          <Popover>
            <PopoverTrigger
              render={<Button type="button" variant="outline" size="sm" />}
            >
              <Columns3 aria-hidden="true" />
              {labels.columns}
            </PopoverTrigger>
            <PopoverContent
              align="start"
              className="max-h-[min(70dvh,var(--available-height))] w-[min(40rem,calc(100vw-2rem))] overflow-y-auto"
            >
              <PopoverTitle className="text-sm font-semibold">
                {labels.columns}
              </PopoverTitle>
              <PopoverDescription className="mt-1 text-xs leading-5 text-muted-foreground">
                {labels.columnDescription}
              </PopoverDescription>
              <div className="mt-4 grid gap-3">
                {orderedLeaves.map((column, index) => {
                  const visible =
                    resolved.columns.visibility[column.id] !== false;
                  const hideDisabled =
                    column.definition.enableHiding === false ||
                    (visible && column.accessor && visibleAccessors <= 1);
                  const pinned = resolved.columns.pinning.left?.includes(
                    column.id,
                  )
                    ? "left"
                    : resolved.columns.pinning.right?.includes(column.id)
                      ? "right"
                      : "";
                  return (
                    <div
                      key={column.id}
                      className="grid gap-2 rounded-lg border border-border p-3 sm:grid-cols-[minmax(0,1fr)_7rem_6rem]"
                    >
                      <div className="flex min-w-0 items-center gap-2">
                        <Checkbox
                          checked={visible}
                          disabled={hideDisabled}
                          aria-label={`${labels.showColumn}: ${column.label}`}
                          onCheckedChange={(visible) =>
                            updateColumns((previous) => ({
                              ...previous,
                              visibility: {
                                ...previous.visibility,
                                [column.id]: visible,
                              },
                            }))
                          }
                        />
                        <span className="min-w-0 flex-1 truncate text-xs font-medium">
                          {column.label}
                        </span>
                        {[-1, 1].map((direction) => (
                          <Button
                            key={direction}
                            type="button"
                            variant="ghost"
                            size="icon-sm"
                            disabled={
                              direction < 0
                                ? index === 0
                                : index === orderedLeaves.length - 1
                            }
                            aria-label={`${direction < 0 ? labels.moveEarlier : labels.moveLater}: ${column.label}`}
                            onClick={() =>
                              updateColumns((previous) => {
                                const order = orderedLeaves.map(
                                  (column) => column.id,
                                );
                                [order[index], order[index + direction]] = [
                                  order[index + direction],
                                  order[index],
                                ];
                                return { ...previous, order };
                              })
                            }
                          >
                            {direction < 0 ? (
                              <ArrowUp aria-hidden="true" />
                            ) : (
                              <ArrowDown aria-hidden="true" />
                            )}
                          </Button>
                        ))}
                      </div>
                      <Select
                        aria-label={`${labels.pin}: ${column.label}`}
                        options={[
                          { value: "", label: labels.unpinned },
                          { value: "left", label: labels.pinLeft },
                          { value: "right", label: labels.pinRight },
                        ]}
                        value={pinned}
                        onValueChange={(side) =>
                          updateColumns((previous) => ({
                            ...previous,
                            pinning: {
                              left: [
                                ...(previous.pinning.left ?? []).filter(
                                  (id) => id !== column.id,
                                ),
                                ...(side === "left" ? [column.id] : []),
                              ],
                              right: [
                                ...(previous.pinning.right ?? []).filter(
                                  (id) => id !== column.id,
                                ),
                                ...(side === "right" ? [column.id] : []),
                              ],
                            },
                          }))
                        }
                      />
                      <Input
                        type="number"
                        min={column.definition.minSize ?? 20}
                        max={column.definition.maxSize}
                        step={1}
                        aria-label={`${labels.width}: ${column.label}`}
                        placeholder={String(column.definition.size ?? 150)}
                        value={resolved.columns.sizing[column.id] ?? ""}
                        onChange={(event) =>
                          updateColumns((previous) => {
                            const sizing = { ...previous.sizing };
                            const width =
                              event.target.value === ""
                                ? undefined
                                : Number(event.target.value);
                            if (width === undefined) delete sizing[column.id];
                            else if (Number.isFinite(width) && width > 0)
                              sizing[column.id] = width;
                            return { ...previous, sizing };
                          })
                        }
                        onBlur={(event) => {
                          if (!event.target.value) return;
                          const width = Math.min(
                            column.definition.maxSize ??
                              Number.MAX_SAFE_INTEGER,
                            Math.max(
                              column.definition.minSize ?? 20,
                              Number(event.target.value),
                            ),
                          );
                          updateColumns((previous) => ({
                            ...previous,
                            sizing: { ...previous.sizing, [column.id]: width },
                          }));
                        }}
                      />
                    </div>
                  );
                })}
              </div>
            </PopoverContent>
          </Popover>
        )}
        <Select
          aria-label={labels.density}
          className="w-full sm:ml-auto sm:w-36"
          value={resolved.density}
          options={[
            { value: "comfortable", label: labels.comfortable },
            { value: "compact", label: labels.compact },
          ]}
          onValueChange={(density) =>
            emit((previous) => ({
              ...previous,
              density: density === "compact" ? "compact" : "comfortable",
            }))
          }
        />
        {onSaveView && (
          <Popover
            open={saveOpen}
            onOpenChange={(open) => {
              setSaveOpen(open);
              if (open) {
                setViewName(activeView?.name ?? "");
                setActionError(undefined);
              }
            }}
          >
            <PopoverTrigger
              render={
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={Boolean(pendingAction)}
                />
              }
            >
              <Save aria-hidden="true" />
              {labels.saveView}
            </PopoverTrigger>
            <PopoverContent
              align="end"
              className="w-[min(22rem,calc(100vw-2rem))]"
            >
              <PopoverTitle className="text-sm font-semibold">
                {labels.saveView}
              </PopoverTitle>
              <label className="mt-4 grid gap-2 text-xs font-medium">
                {labels.viewName}
                <Input
                  value={viewName}
                  onChange={(event) => setViewName(event.target.value)}
                  maxLength={100}
                />
              </label>
              <div className="mt-4 flex flex-wrap justify-end gap-2">
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  disabled={Boolean(pendingAction)}
                  onClick={() => setSaveOpen(false)}
                >
                  {labels.cancel}
                </Button>
                {activeView && (
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    disabled={!viewName.trim() || Boolean(pendingAction)}
                    onClick={() => saveView(true)}
                  >
                    {labels.saveNewView}
                  </Button>
                )}
                <Button
                  type="button"
                  size="sm"
                  loading={pendingAction === "save"}
                  disabled={!viewName.trim() || Boolean(pendingAction)}
                  onClick={() => saveView(false)}
                >
                  {labels.save}
                </Button>
              </div>
            </PopoverContent>
          </Popover>
        )}
        {onDeleteView && activeView && (
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label={`${labels.deleteView}: ${activeView.name}`}
            loading={pendingAction === "delete"}
            disabled={Boolean(pendingAction)}
            onClick={() => {
              void runAction("delete", async () => {
                await onDeleteView(activeView.id);
                setActiveView(undefined);
              });
            }}
          >
            <Trash2 aria-hidden="true" />
          </Button>
        )}
        {onShareView && (
          <Button
            type="button"
            variant="outline"
            size="sm"
            loading={pendingAction === "share"}
            disabled={Boolean(pendingAction)}
            onClick={() => {
              void runAction("share", () =>
                onShareView(resolveValue(current.current), activeView),
              );
            }}
          >
            <Share2 aria-hidden="true" />
            {labels.shareView}
          </Button>
        )}
      </div>
      {actionError && (
        <Alert variant="destructive" title={labels.actionError}>
          {actionError}
        </Alert>
      )}
      {chipCount > 0 && (
        <div className="flex flex-wrap items-center gap-2">
          <ul
            aria-label={labels.activeFilters}
            className="flex min-w-0 flex-wrap gap-2"
          >
            {[
              ...(resolved.query.search
                ? [
                    {
                      id: "search",
                      label: `${labels.search}: ${resolved.query.search}`,
                      filterId: undefined,
                    },
                  ]
                : []),
              ...resolved.query.filters.map((filter) => {
                const field = filterFields.find(
                  (field) => field.id === filter.id,
                );
                const label =
                  field?.label ??
                  leaves.find((column) => column.id === filter.id)?.label ??
                  filter.id;
                return {
                  id: `filter:${filter.id}`,
                  label: `${label}: ${filterLabel(filter.value, field, labels)}`,
                  filterId: filter.id,
                };
              }),
            ].map((chip) => (
              <li
                key={chip.id}
                className="flex min-w-0 max-w-full items-center gap-1 rounded-full border border-border bg-accent/55 py-1 pr-1 pl-3 text-xs"
              >
                <span className="truncate text-foreground">{chip.label}</span>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-sm"
                  className="size-7 shrink-0 rounded-full"
                  aria-label={`${labels.removeFilter}: ${chip.label}`}
                  onClick={() => {
                    if (chip.filterId !== undefined) {
                      setFilter(chip.filterId, undefined);
                    } else {
                      emit((previous) => ({
                        ...previous,
                        query: {
                          ...previous.query,
                          search: "",
                          pagination: {
                            ...previous.query.pagination,
                            pageIndex: 0,
                          },
                        },
                      }));
                    }
                  }}
                >
                  <X aria-hidden="true" className="size-3" />
                </Button>
              </li>
            ))}
          </ul>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={clearFilters}
          >
            {labels.clearFilters}
          </Button>
        </div>
      )}
      <DataTable
        {...tableProps}
        columns={configuredColumns}
        query={resolved.query}
        onQueryChange={(query) => emit((previous) => ({ ...previous, query }))}
        columnState={resolved.columns}
        onColumnStateChange={(columns) =>
          emit((previous) => ({ ...previous, columns }))
        }
        density={resolved.density}
        labels={tableLabels}
      />
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import {
  Crown,
  Mail,
  Plus,
  RotateCcw,
  Search,
  ShieldCheck,
  Trash2,
  Users,
} from "lucide-react";
import { z } from "zod";
import { Alert } from "@/components/ui/alert";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogTitle,
} from "@/components/ui/dialog";
import { Empty } from "@/components/ui/empty";
import { Field } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { cn } from "@/lib/utils";

export type MemberRole = "owner" | "admin" | "member" | "viewer";
export type InvitationRole = Exclude<MemberRole, "owner">;
export type ManagedMember = {
  id: string;
  name: string;
  avatarSrc?: string;
  email: string;
  role: MemberRole;
  status: "active" | "suspended";
  joinedAt: string;
};
export type ManagedInvitation = {
  id: string;
  email: string;
  role: InvitationRole;
  status: "pending" | "accepted" | "expired" | "revoked";
  expiresAt: string;
};
export type MemberManagementProps = {
  members: ManagedMember[];
  invitations: ManagedInvitation[];
  currentMemberId: string;
  canManage: boolean;
  canTransferOwnership?: boolean;
  onInvite: (email: string, role: InvitationRole) => void | Promise<void>;
  onChangeRole: (id: string, role: InvitationRole) => void | Promise<void>;
  onRemoveMember: (id: string) => void | Promise<void>;
  onResendInvitation: (id: string) => void | Promise<void>;
  onAcceptInvitation: (id: string) => void | Promise<void>;
  onRevokeInvitation: (id: string) => void | Promise<void>;
  onTransferOwnership: (id: string) => void | Promise<void>;
  locale?: "en" | "es";
  className?: string;
};

type Confirmation = { kind: "remove" | "revoke" | "transfer"; id: string };
const emailSchema = z.email();
function assignableRole(value: string): value is InvitationRole {
  return value === "admin" || value === "member" || value === "viewer";
}

/** The caller owns every member/invitation mutation and its permission boundary. */
export function MemberManagement({
  members,
  invitations,
  currentMemberId,
  canManage,
  canTransferOwnership = false,
  onInvite,
  onChangeRole,
  onRemoveMember,
  onResendInvitation,
  onAcceptInvitation,
  onRevokeInvitation,
  onTransferOwnership,
  locale = "en",
  className,
}: MemberManagementProps) {
  const l = (en: string, es: string) => (locale === "es" ? es : en);
  const id = useId();
  const mounted = useRef(false);
  const inFlight = useRef(false);
  const [query, setQuery] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<InvitationRole>("member");
  const [emailError, setEmailError] = useState("");
  const [pending, setPending] = useState("");
  const [failure, setFailure] = useState("");
  const [notice, setNotice] = useState("");
  const [confirmation, setConfirmation] = useState<Confirmation | null>(null);
  const owners = members.filter((member) => member.role === "owner");
  const activeOwners = owners.filter((member) => member.status === "active");
  const busy = !!pending;
  const roleLabels: Record<MemberRole, string> = {
    owner: l("Owner", "Propietario"),
    admin: l("Admin", "Administrador"),
    member: l("Member", "Miembro"),
    viewer: l("Viewer", "Lector"),
  };
  const roles = (["admin", "member", "viewer"] as const).map((value) => ({
    value,
    label: roleLabels[value],
  }));
  const statusLabels: Record<ManagedInvitation["status"], string> = {
    pending: l("Pending", "Pendiente"),
    accepted: l("Accepted", "Aceptada"),
    expired: l("Expired", "Caducada"),
    revoked: l("Revoked", "Revocada"),
  };
  const normalizedQuery = query.trim().toLocaleLowerCase(locale);
  const visibleMembers = members.filter((member) =>
    `${member.name} ${member.email}`
      .toLocaleLowerCase(locale)
      .includes(normalizedQuery),
  );
  const visibleInvitations = invitations.filter((invitation) =>
    invitation.email.toLocaleLowerCase(locale).includes(normalizedQuery),
  );
  const protectedOwner = (member: ManagedMember) =>
    member.role === "owner" &&
    (owners.length <= 1 ||
      (member.status === "active" && activeOwners.length <= 1));
  const editable = (member: ManagedMember) =>
    canManage && member.id !== currentMemberId && !protectedOwner(member);
  const transferable = (member: ManagedMember) =>
    canManage &&
    canTransferOwnership &&
    member.id !== currentMemberId &&
    member.role !== "owner" &&
    member.status === "active";
  const formatDate = (value: string) => {
    const parsed = new Date(
      /^\d{4}-\d{2}-\d{2}$/.test(value) ? `${value}T12:00:00` : value,
    );
    return Number.isNaN(parsed.getTime())
      ? l("Not available", "No disponible")
      : new Intl.DateTimeFormat(locale, {
          year: "numeric",
          month: "short",
          day: "numeric",
        }).format(parsed);
  };
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const run = async (
    label: string,
    action: () => void | Promise<void>,
    success: string,
  ) => {
    if (!canManage || inFlight.current) return false;
    inFlight.current = true;
    setPending(label);
    setFailure("");
    setNotice("");
    try {
      await action();
      if (mounted.current) setNotice(success);
      return true;
    } catch (cause) {
      if (mounted.current)
        setFailure(
          cause instanceof Error && cause.message
            ? cause.message
            : l(
                "The change could not be completed. Try again.",
                "No se pudo completar el cambio. Reintenta.",
              ),
        );
      return false;
    } finally {
      inFlight.current = false;
      if (mounted.current) setPending("");
    }
  };
  const invite = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canManage || inFlight.current) return;
    const normalized = email.trim().toLowerCase();
    if (!emailSchema.safeParse(normalized).success) {
      setEmailError(
        l("Enter a valid email address.", "Escribe un correo válido."),
      );
      return;
    }
    if (
      members.some(
        (member) => member.email.trim().toLowerCase() === normalized,
      ) ||
      invitations.some(
        (invitation) =>
          invitation.status === "pending" &&
          invitation.email.trim().toLowerCase() === normalized,
      )
    ) {
      setEmailError(
        l(
          "This email already belongs to a member or pending invitation.",
          "Este correo ya pertenece a un miembro o invitación pendiente.",
        ),
      );
      return;
    }
    setEmailError("");
    if (
      (await run(
        "invite",
        () => onInvite(normalized, role),
        l(
          "Invitation created in this preview.",
          "Invitación creada en esta vista previa.",
        ),
      )) &&
      mounted.current
    ) {
      setEmail("");
    }
  };
  const confirm = async () => {
    if (!confirmation || !canManage || inFlight.current) return;
    const member = members.find((item) => item.id === confirmation.id);
    const invitation = invitations.find((item) => item.id === confirmation.id);
    const allowed =
      confirmation.kind === "remove"
        ? member && editable(member)
        : confirmation.kind === "transfer"
          ? member && transferable(member)
          : invitation &&
            (invitation.status === "pending" ||
              invitation.status === "expired");
    if (!allowed) {
      setFailure(
        l(
          "This action is no longer available. Review the current list.",
          "Esta acción ya no está disponible. Revisa la lista actual.",
        ),
      );
      setConfirmation(null);
      return;
    }
    const callback =
      confirmation.kind === "remove"
        ? onRemoveMember
        : confirmation.kind === "transfer"
          ? onTransferOwnership
          : onRevokeInvitation;
    const success =
      confirmation.kind === "remove"
        ? l("Member removed.", "Miembro eliminado.")
        : confirmation.kind === "transfer"
          ? l("Ownership transferred.", "Propiedad transferida.")
          : l("Invitation revoked.", "Invitación revocada.");
    if (
      (await run(
        confirmation.kind,
        () => callback(confirmation.id),
        success,
      )) &&
      mounted.current
    )
      setConfirmation(null);
  };
  const confirmedMember = members.find(
    (member) => member.id === confirmation?.id,
  );
  const confirmedInvitation = invitations.find(
    (invitation) => invitation.id === confirmation?.id,
  );
  const target =
    confirmation?.kind === "revoke"
      ? confirmedInvitation?.email
      : confirmedMember?.name;

  return (
    <section
      aria-label={l("Members and invitations", "Miembros e invitaciones")}
      aria-busy={busy}
      className={cn("grid min-w-0 gap-5", className)}
    >
      {!canManage && (
        <Alert title={l("View access", "Acceso de lectura")}>
          {l(
            "You can review the team. Ask a workspace administrator to manage members and invitations.",
            "Puedes consultar el equipo. Pide a un administrador que gestione miembros e invitaciones.",
          )}
        </Alert>
      )}
      <Card appearance="elevated">
        <CardHeader className="border-b border-primary/15 bg-[radial-gradient(ellipse_at_top_right,var(--accent),transparent_75%)]">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <span className="rounded-xl border border-primary/20 bg-accent p-3 text-primary">
                <Users aria-hidden="true" className="size-5" />
              </span>
              <CardTitle>{l("Your team", "Tu equipo")}</CardTitle>
            </div>
            <Badge variant="outline">
              {members.length} {l("members", "miembros")}
            </Badge>
          </div>
          <CardDescription>
            {l(
              "Keep responsibilities clear. Your own access and the last owner are protected.",
              "Mantén claras las responsabilidades. Tu propio acceso y el último propietario están protegidos.",
            )}
          </CardDescription>
        </CardHeader>
        <CardContent className="grid gap-5 pt-5">
          <Field
            htmlFor={`${id}-search`}
            label={l(
              "Search members and invitations",
              "Buscar miembros e invitaciones",
            )}
          >
            <Input
              type="search"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={l("Name or email", "Nombre o correo")}
            />
          </Field>
          {visibleMembers.length ? (
            <ul
              className="grid gap-3"
              aria-label={l("Workspace members", "Miembros del espacio")}
            >
              {visibleMembers.map((member) => (
                <li
                  key={member.id}
                  className="grid min-w-0 gap-4 rounded-xl border border-border bg-surface p-4 xl:grid-cols-[minmax(0,1fr)_180px_auto] xl:items-center"
                >
                  <div className="flex min-w-0 items-start gap-3">
                    <Avatar
                      name={member.name}
                      src={member.avatarSrc}
                      className="size-9"
                    />
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <h3 className="break-words text-sm font-semibold">
                          {member.name}
                        </h3>
                        {member.id === currentMemberId && (
                          <Badge variant="outline">{l("You", "Tú")}</Badge>
                        )}
                        <Badge
                          variant={
                            member.status === "active" ? "default" : "warning"
                          }
                        >
                          {member.status === "active"
                            ? l("Active", "Activo")
                            : l("Suspended", "Suspendido")}
                        </Badge>
                      </div>
                      <p className="mt-1 break-all text-xs text-muted-foreground">
                        {member.email}
                      </p>
                      <p className="mt-2 text-xs text-muted-foreground">
                        {l("Joined", "Se unió")} {formatDate(member.joinedAt)}
                        {protectedOwner(member) &&
                          ` · ${l("Last owner protected", "Último propietario protegido")}`}
                      </p>
                    </div>
                  </div>
                  {canManage ? (
                    <Field
                      htmlFor={`${id}-role-${member.id}`}
                      label={`${l("Role for", "Rol de")} ${member.name}`}
                    >
                      <Select
                        value={member.role}
                        disabled={busy || !editable(member)}
                        options={[
                          {
                            value: "owner",
                            label: roleLabels.owner,
                            disabled: true,
                          },
                          ...roles,
                        ]}
                        onValueChange={(next) => {
                          if (
                            !editable(member) ||
                            !assignableRole(next) ||
                            next === member.role
                          )
                            return;
                          void run(
                            `role-${member.id}`,
                            () => onChangeRole(member.id, next),
                            l(
                              "Member role updated.",
                              "Rol del miembro actualizado.",
                            ),
                          );
                        }}
                      />
                    </Field>
                  ) : (
                    <Badge variant="outline" className="justify-self-start">
                      {roleLabels[member.role]}
                    </Badge>
                  )}
                  {canManage && (
                    <div className="flex flex-wrap items-center gap-2">
                      {transferable(member) && (
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
                          disabled={busy}
                          aria-label={`${l("Transfer ownership to", "Transferir propiedad a")} ${member.name}`}
                          onClick={() => {
                            setFailure("");
                            setConfirmation({
                              kind: "transfer",
                              id: member.id,
                            });
                          }}
                        >
                          <Crown aria-hidden="true" />
                          {l("Transfer", "Transferir")}
                        </Button>
                      )}
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        disabled={busy || !editable(member)}
                        aria-label={`${l("Remove member", "Eliminar miembro")} ${member.name}`}
                        onClick={() => {
                          if (editable(member)) {
                            setFailure("");
                            setConfirmation({ kind: "remove", id: member.id });
                          }
                        }}
                      >
                        <Trash2 aria-hidden="true" />
                        {l("Remove", "Eliminar")}
                      </Button>
                    </div>
                  )}
                </li>
              ))}
            </ul>
          ) : (
            <Empty
              title={
                query
                  ? l("No matching members", "No hay miembros que coincidan")
                  : l("No members yet", "Aún no hay miembros")
              }
              description={
                query
                  ? l(
                      "Try another name or email.",
                      "Prueba otro nombre o correo.",
                    )
                  : l(
                      "Members will appear here when they join.",
                      "Los miembros aparecerán aquí cuando se unan.",
                    )
              }
              action={
                query ? (
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setQuery("")}
                  >
                    <Search aria-hidden="true" />
                    {l("Clear search", "Limpiar búsqueda")}
                  </Button>
                ) : undefined
              }
            />
          )}
        </CardContent>
      </Card>
      <Card>
        <CardHeader>
          <div className="flex flex-wrap items-center justify-between gap-3">
            <CardTitle className="flex items-center gap-2">
              <Mail aria-hidden="true" className="size-4 text-primary" />
              {l("Invitations", "Invitaciones")}
            </CardTitle>
            <Badge variant="outline">
              {invitations.filter((item) => item.status === "pending").length}{" "}
              {l("pending", "pendientes")}
            </Badge>
          </div>
          <CardDescription>
            {l(
              "Invitation actions are previews. Accept in demo changes the preview; this component does not send emails.",
              "Las acciones son vistas previas. Aceptar en demo modifica la vista previa; este componente no envía correos.",
            )}
          </CardDescription>
        </CardHeader>
        <CardContent className="grid gap-5">
          {canManage && (
            <form
              noValidate
              onSubmit={(event) => void invite(event)}
              className="grid items-end gap-3 rounded-xl border border-primary/20 bg-accent/30 p-4 sm:grid-cols-[minmax(0,1fr)_160px_auto]"
            >
              <Field
                htmlFor={`${id}-invite-email`}
                label={l("Email address", "Correo electrónico")}
                error={emailError}
              >
                <Input
                  type="email"
                  name="email"
                  autoComplete="email"
                  value={email}
                  disabled={busy}
                  onChange={(event) => {
                    setEmail(event.target.value);
                    setEmailError("");
                  }}
                  placeholder="name@example.com"
                />
              </Field>
              <Field
                htmlFor={`${id}-invite-role`}
                label={l("Invitation role", "Rol de invitación")}
              >
                <Select
                  value={role}
                  options={roles}
                  disabled={busy}
                  onValueChange={(next) => {
                    if (assignableRole(next)) setRole(next);
                  }}
                />
              </Field>
              <Button
                type="submit"
                appearance="gradient"
                disabled={busy}
                loading={pending === "invite"}
              >
                <Plus aria-hidden="true" />
                {l("Create invitation", "Crear invitación")}
              </Button>
            </form>
          )}
          {visibleInvitations.length ? (
            <ul
              className="grid gap-3"
              aria-label={l(
                "Workspace invitations",
                "Invitaciones del espacio",
              )}
            >
              {visibleInvitations.map((invitation) => (
                <li
                  key={invitation.id}
                  className="flex min-w-0 flex-col gap-3 rounded-xl border border-border p-4 lg:flex-row lg:items-center"
                >
                  <div className="min-w-0 flex-1">
                    <p className="break-all text-sm font-semibold">
                      {invitation.email}
                    </p>
                    <p className="mt-1 text-xs leading-6 text-muted-foreground">
                      {roleLabels[invitation.role]} · {l("Expires", "Caduca")}{" "}
                      {formatDate(invitation.expiresAt)}
                    </p>
                  </div>
                  <Badge
                    variant={
                      invitation.status === "expired"
                        ? "warning"
                        : invitation.status === "revoked"
                          ? "neutral"
                          : "outline"
                    }
                    className="self-start lg:self-center"
                  >
                    {statusLabels[invitation.status]}
                  </Badge>
                  {canManage &&
                    (invitation.status === "pending" ||
                      invitation.status === "expired") && (
                      <div className="flex flex-wrap gap-2">
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
                          disabled={busy}
                          aria-label={`${l("Refresh invitation for", "Renovar invitación de")} ${invitation.email}`}
                          onClick={() =>
                            void run(
                              `resend-${invitation.id}`,
                              () => onResendInvitation(invitation.id),
                              l(
                                "Invitation refreshed in this preview.",
                                "Invitación renovada en esta vista previa.",
                              ),
                            )
                          }
                        >
                          <RotateCcw aria-hidden="true" />
                          {l("Refresh invitation", "Renovar invitación")}
                        </Button>
                        {invitation.status === "pending" && (
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            disabled={busy}
                            aria-label={`${l("Accept in demo for", "Aceptar en demo para")} ${invitation.email}`}
                            onClick={() =>
                              void run(
                                `accept-${invitation.id}`,
                                () => onAcceptInvitation(invitation.id),
                                l(
                                  "Invitation accepted in this preview.",
                                  "Invitación aceptada en esta vista previa.",
                                ),
                              )
                            }
                          >
                            {l("Accept in demo", "Aceptar en demo")}
                          </Button>
                        )}
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          disabled={busy}
                          aria-label={`${l("Revoke invitation for", "Revocar invitación de")} ${invitation.email}`}
                          onClick={() => {
                            setFailure("");
                            setConfirmation({
                              kind: "revoke",
                              id: invitation.id,
                            });
                          }}
                        >
                          <Trash2 aria-hidden="true" />
                          {l("Revoke", "Revocar")}
                        </Button>
                      </div>
                    )}
                </li>
              ))}
            </ul>
          ) : (
            <Empty
              title={
                query
                  ? l(
                      "No matching invitations",
                      "No hay invitaciones que coincidan",
                    )
                  : l("No invitations yet", "Aún no hay invitaciones")
              }
              description={
                query
                  ? l("Try another email address.", "Prueba otro correo.")
                  : l(
                      "Create an invitation when you are ready to grow the team.",
                      "Crea una invitación cuando quieras ampliar el equipo.",
                    )
              }
            />
          )}
        </CardContent>
      </Card>
      {busy && (
        <p role="status" className="text-xs text-muted-foreground">
          {l("Applying your change…", "Aplicando tu cambio…")}
        </p>
      )}
      {notice && (
        <Alert
          variant="success"
          title={l("Change completed", "Cambio completado")}
        >
          {notice}
        </Alert>
      )}
      {failure && (
        <Alert
          variant="destructive"
          title={l(
            "The change needs another try",
            "Hay que reintentar el cambio",
          )}
        >
          {failure}
        </Alert>
      )}
      <Dialog
        open={!!confirmation}
        onOpenChange={(open) => {
          if (!open && !inFlight.current) {
            setConfirmation(null);
            setFailure("");
          }
        }}
      >
        <DialogContent
          closeLabel={l("Close confirmation", "Cerrar confirmación")}
        >
          <DialogTitle>
            {confirmation?.kind === "transfer"
              ? l(
                  "Transfer workspace ownership?",
                  "¿Transferir la propiedad del espacio?",
                )
              : confirmation?.kind === "remove"
                ? l("Remove this member?", "¿Eliminar este miembro?")
                : l("Revoke this invitation?", "¿Revocar esta invitación?")}
          </DialogTitle>
          <DialogDescription>
            {confirmation?.kind === "transfer"
              ? l(
                  `Make ${target ?? ""} the owner. Your own role may change when this completes.`,
                  `Haz propietario a ${target ?? ""}. Tu propio rol puede cambiar al completar la acción.`,
                )
              : confirmation?.kind === "remove"
                ? l(
                    `${target ?? ""} will lose access to this workspace.`,
                    `${target ?? ""} perderá acceso a este espacio.`,
                  )
                : l(
                    `Cancel the invitation for ${target ?? ""}.`,
                    `Cancela la invitación de ${target ?? ""}.`,
                  )}
          </DialogDescription>
          {confirmation?.kind === "transfer" && (
            <p className="mt-4 flex items-start gap-2 rounded-lg bg-accent p-3 text-xs leading-6 text-accent-foreground">
              <ShieldCheck
                aria-hidden="true"
                className="mt-1 size-4 shrink-0"
              />
              {l(
                "Ownership must move to an active member. Your application completes the transfer together.",
                "La propiedad debe pasar a un miembro activo. Tu aplicación completa la transferencia como una sola operación.",
              )}
            </p>
          )}
          {failure && (
            <Alert
              variant="destructive"
              title={l("Try again", "Reintenta")}
              className="mt-4"
            >
              {failure}
            </Alert>
          )}
          <DialogFooter className="flex-wrap">
            <Button
              type="button"
              variant="outline"
              disabled={busy}
              onClick={() => {
                setConfirmation(null);
                setFailure("");
              }}
            >
              {l("Cancel", "Cancelar")}
            </Button>
            <Button
              type="button"
              variant={
                confirmation?.kind === "transfer" ? "default" : "destructive"
              }
              disabled={!canManage || busy}
              loading={busy && pending === confirmation?.kind}
              onClick={() => void confirm()}
            >
              {confirmation?.kind === "transfer"
                ? l("Transfer ownership", "Transferir propiedad")
                : confirmation?.kind === "remove"
                  ? l("Remove member", "Eliminar miembro")
                  : l("Revoke invitation", "Revocar invitación")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </section>
  );
}

import type { ReactNode } from "react";
import { ArrowDownRight, ArrowUpRight } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
export type MetricCardProps = {
  label: string;
  value: string;
  change?: string;
  trend?: "up" | "down";
  note?: string;
  icon?: ReactNode;
  series?: number[];
  className?: string;
};
export function MetricCard({
  label,
  value,
  change,
  trend = "up",
  note,
  icon,
  series,
  className,
}: MetricCardProps) {
  const max = Math.max(1, ...(series ?? [])),
    min = Math.min(0, ...(series ?? []));
  const points = series
    ?.map(
      (n, i) =>
        `${(i / Math.max(1, series.length - 1)) * 72},${24 - ((n - min) / (max - min)) * 22}`,
    )
    .join(" ");
  return (
    <Card
      className={cn(
        "relative isolate overflow-hidden p-[var(--af-card-padding,24px)]",
        className,
      )}
    >
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-px opacity-70"
        style={{
          background:
            "linear-gradient(90deg, transparent, var(--chart-1), var(--chart-2), transparent)",
        }}
      />
      <span
        aria-hidden="true"
        className="pointer-events-none absolute -top-12 -right-12 -z-10 size-40 rounded-full"
        style={{
          background:
            "radial-gradient(circle, color-mix(in srgb, var(--primary) 12%, transparent), transparent 70%)",
        }}
      />
      <div className="flex items-start justify-between gap-3">
        <p className="pt-1 text-[13px] leading-5 font-medium text-muted-foreground">
          {label}
        </p>
        {icon && (
          <span
            aria-hidden="true"
            className="flex size-9 shrink-0 items-center justify-center rounded-xl border border-primary/20 bg-accent/65 text-primary [&_svg]:size-4"
          >
            {icon}
          </span>
        )}
      </div>
      <p className="mt-4 break-words text-[30px] leading-tight font-semibold tracking-[-1.2px] tabular-nums sm:text-[32px]">
        {value}
      </p>
      <div className="mt-4 flex min-h-7 flex-wrap items-center gap-x-2 gap-y-2">
        {change && (
          <Badge
            variant={trend === "up" ? "default" : "destructive"}
            className="px-2 py-0.5 text-[11px]"
          >
            {trend === "up" ? (
              <ArrowUpRight aria-hidden="true" />
            ) : (
              <ArrowDownRight aria-hidden="true" />
            )}
            {change}
          </Badge>
        )}
        {note && (
          <span className="text-[11px] leading-5 text-muted-foreground">
            {note}
          </span>
        )}
        {points && (
          <svg
            className="ml-auto h-8 w-20 shrink-0 text-primary"
            viewBox="0 0 72 30"
            fill="none"
            aria-hidden="true"
          >
            <polygon
              points={`0,30 ${points} 72,30`}
              fill="currentColor"
              opacity=".12"
            />
            <polyline
              points={points}
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </div>
    </Card>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import {
  ArrowLeft,
  ArrowRight,
  Building2,
  Check,
  Database,
  Layers,
  Plus,
  Upload,
  Users,
  X,
} from "lucide-react";
import { z } from "zod";
import { Alert } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Field } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { cn } from "@/lib/utils";

export type OnboardingInviteRole = "admin" | "member" | "viewer";
export type OnboardingFlowValue = {
  step: number;
  organizationName: string;
  workspaceName: string;
  workspaceSlug: string;
  invites: { email: string; role: OnboardingInviteRole }[];
  completed: boolean;
};
export type OnboardingFlowProps = {
  value: OnboardingFlowValue;
  onChange: (next: OnboardingFlowValue) => void;
  /** Commit completion in the caller, including any newly created workspace ID. */
  onComplete: (value: OnboardingFlowValue) => void | Promise<void>;
  onOpenCustomers?: () => void;
  onOpenImports?: () => void;
  locale?: "en" | "es";
  className?: string;
};

type Errors = Partial<
  Record<
    "organizationName" | "workspaceName" | "workspaceSlug" | "invite",
    string
  >
>;
const emailSchema = z.email();
const slugPattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
function slugFor(name: string) {
  return name
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 64)
    .replace(/-+$/, "");
}
function inviteRole(value: string): value is OnboardingInviteRole {
  return value === "admin" || value === "member" || value === "viewer";
}

/** Business values and resume persistence belong to the caller. */
export function OnboardingFlow({
  value,
  onChange,
  onComplete,
  onOpenCustomers,
  onOpenImports,
  locale = "en",
  className,
}: OnboardingFlowProps) {
  const l = (en: string, es: string) => (locale === "es" ? es : en);
  const id = useId();
  const heading = useRef<HTMLHeadingElement>(null);
  const mounted = useRef(false);
  const inFlight = useRef(false);
  const [errors, setErrors] = useState<Errors>({});
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<OnboardingInviteRole>("member");
  const [saving, setSaving] = useState(false);
  const [failure, setFailure] = useState("");
  const step = Number.isFinite(value.step)
    ? Math.max(0, Math.min(3, Math.trunc(value.step)))
    : 0;
  const steps = [
    l("Organization", "Organización"),
    l("Workspace", "Espacio de trabajo"),
    l("Invite your team", "Invita a tu equipo"),
    l("Your first record", "Tu primer registro"),
  ];
  const titles = [
    l("Give your organization a home.", "Dale un hogar a tu organización."),
    l("Make room for your work.", "Crea un espacio para tu trabajo."),
    l("Good work starts together.", "El buen trabajo empieza en equipo."),
    l("A clear first step.", "Un primer paso claro."),
  ];
  const roles = [
    { value: "admin", label: l("Admin", "Administrador") },
    { value: "member", label: l("Member", "Miembro") },
    { value: "viewer", label: l("Viewer", "Lector") },
  ];

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  useEffect(() => {
    heading.current?.focus();
  }, [step, value.completed]);

  const change = (next: Partial<OnboardingFlowValue>) => {
    if (inFlight.current) return;
    onChange({ ...value, ...next });
    setErrors({});
    setFailure("");
  };
  const validate = (target: number): Errors => {
    const next: Errors = {};
    if (
      target >= 0 &&
      (value.organizationName.trim().length < 2 ||
        value.organizationName.trim().length > 100)
    ) {
      next.organizationName = l(
        "Use 2–100 characters for the organization name.",
        "Usa entre 2 y 100 caracteres para la organización.",
      );
    }
    if (target >= 1) {
      if (
        value.workspaceName.trim().length < 2 ||
        value.workspaceName.trim().length > 100
      ) {
        next.workspaceName = l(
          "Use 2–100 characters for the workspace name.",
          "Usa entre 2 y 100 caracteres para el espacio.",
        );
      }
      if (
        !slugPattern.test(value.workspaceSlug) ||
        value.workspaceSlug.length < 2 ||
        value.workspaceSlug.length > 64
      ) {
        next.workspaceSlug = l(
          "Use 2–64 lowercase letters, numbers and single hyphens.",
          "Usa entre 2 y 64 letras minúsculas, números y guiones simples.",
        );
      }
    }
    return next;
  };
  const queuedInvites = () => {
    if (!email.trim()) return value.invites;
    const normalized = email.trim().toLowerCase();
    if (!emailSchema.safeParse(normalized).success) {
      setErrors({
        invite: l("Enter a valid email address.", "Escribe un correo válido."),
      });
      return null;
    }
    if (
      value.invites.some(
        (item) => item.email.trim().toLowerCase() === normalized,
      )
    ) {
      setErrors({
        invite: l(
          "This email is already on the invitation list.",
          "Este correo ya está en la lista de invitaciones.",
        ),
      });
      return null;
    }
    return [...value.invites, { email: normalized, role }];
  };
  const addInvite = () => {
    if (inFlight.current || !email.trim()) return;
    const invites = queuedInvites();
    if (!invites) return;
    change({ invites });
    setEmail("");
  };
  const continueStep = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (inFlight.current || value.completed) return;
    const nextErrors = validate(step);
    if (Object.keys(nextErrors).length) {
      setErrors(nextErrors);
      changeInvalidStep(nextErrors);
      return;
    }
    if (step < 3) {
      const invites = step === 2 ? queuedInvites() : value.invites;
      if (!invites) return;
      change({ step: step + 1, invites });
      setEmail("");
      return;
    }
    const invalidInvitation = value.invites.some(
      (item) =>
        !emailSchema.safeParse(item.email.trim()).success ||
        !inviteRole(item.role),
    );
    const uniqueEmails = new Set(
      value.invites.map((item) => item.email.trim().toLowerCase()),
    );
    if (invalidInvitation || uniqueEmails.size !== value.invites.length) {
      onChange({ ...value, step: 2 });
      setErrors({
        invite: l(
          "Review the invitation emails and roles before finishing.",
          "Revisa los correos y roles antes de terminar.",
        ),
      });
      return;
    }
    const completed: OnboardingFlowValue = {
      ...value,
      step: 3,
      organizationName: value.organizationName.trim(),
      workspaceName: value.workspaceName.trim(),
      invites: value.invites.map((item) => ({
        ...item,
        email: item.email.trim().toLowerCase(),
      })),
      completed: true,
    };
    inFlight.current = true;
    setSaving(true);
    setFailure("");
    try {
      await onComplete(completed);
    } catch (cause) {
      if (mounted.current)
        setFailure(
          cause instanceof Error && cause.message
            ? cause.message
            : l(
                "Setup could not be completed. Your details are still here; try again.",
                "No se pudo completar la configuración. Tus datos siguen aquí; reintenta.",
              ),
        );
    } finally {
      inFlight.current = false;
      if (mounted.current) setSaving(false);
    }
  };
  const changeInvalidStep = (next: Errors) => {
    const target = next.organizationName ? 0 : 1;
    if (target !== step) onChange({ ...value, step: target });
  };

  return (
    <section
      aria-label={l("Workspace setup", "Configuración del espacio")}
      className={cn("grid min-w-0 gap-5", className)}
    >
      <ol
        aria-label={l("Setup progress", "Progreso de configuración")}
        className="grid grid-cols-2 gap-3 lg:grid-cols-4"
      >
        {steps.map((label, index) => (
          <li
            key={label}
            aria-current={
              !value.completed && step === index ? "step" : undefined
            }
            className={cn(
              "flex min-w-0 items-center gap-3 rounded-xl border p-3 text-xs",
              step === index && !value.completed
                ? "border-primary/40 bg-accent text-foreground shadow-sm"
                : "border-border bg-surface text-muted-foreground",
            )}
          >
            <span
              className={cn(
                "flex size-7 shrink-0 items-center justify-center rounded-full border text-xs font-semibold",
                index < step || value.completed
                  ? "border-primary/25 bg-primary text-primary-foreground"
                  : "border-border",
              )}
            >
              {index < step || value.completed ? (
                <Check aria-hidden="true" className="size-3.5" />
              ) : (
                index + 1
              )}
            </span>
            <span className="leading-5">{label}</span>
          </li>
        ))}
      </ol>
      <Card appearance="elevated" className="overflow-hidden">
        <CardHeader className="border-b border-primary/15 bg-[radial-gradient(ellipse_at_top_right,var(--accent),transparent_75%)]">
          <div className="flex items-center justify-between gap-3">
            <span className="flex size-11 items-center justify-center rounded-xl border border-primary/20 bg-accent text-primary">
              {step === 0 ? (
                <Building2 aria-hidden="true" />
              ) : step === 1 ? (
                <Layers aria-hidden="true" />
              ) : step === 2 ? (
                <Users aria-hidden="true" />
              ) : (
                <Database aria-hidden="true" />
              )}
            </span>
            <Badge variant="outline">
              {value.completed
                ? l("Setup complete", "Configuración completa")
                : `${l("Step", "Paso")} ${step + 1} / 4`}
            </Badge>
          </div>
          <CardTitle
            ref={heading}
            tabIndex={-1}
            className="mt-3 text-xl outline-none sm:text-2xl"
          >
            {value.completed
              ? l("Your workspace is ready.", "Tu espacio está listo.")
              : titles[step]}
          </CardTitle>
          <CardDescription>
            {value.completed
              ? l(
                  "Choose your next action when you are ready.",
                  "Elige tu siguiente acción cuando quieras.",
                )
              : l(
                  "Your progress belongs to this workspace. You can return to these details later.",
                  "Tu progreso pertenece a este espacio. Puedes volver a estos datos más tarde.",
                )}
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-6">
          <form
            noValidate
            onSubmit={(event) => void continueStep(event)}
            aria-busy={saving}
            className="grid gap-6"
          >
            {!value.completed && step === 0 && (
              <Field
                htmlFor={`${id}-organization`}
                label={l("Organization name", "Nombre de organización")}
                description={l(
                  "The team or company this workspace belongs to.",
                  "El equipo o empresa al que pertenece este espacio.",
                )}
                error={errors.organizationName}
              >
                <Input
                  name="organizationName"
                  autoComplete="organization"
                  value={value.organizationName}
                  maxLength={100}
                  disabled={saving}
                  onChange={(event) =>
                    change({ organizationName: event.target.value })
                  }
                  placeholder={l(
                    "e.g. Northstar Studio",
                    "p. ej. Estudio Northstar",
                  )}
                />
              </Field>
            )}
            {!value.completed && step === 1 && (
              <div className="grid gap-5">
                <Field
                  htmlFor={`${id}-workspace`}
                  label={l("Workspace name", "Nombre del espacio")}
                  error={errors.workspaceName}
                >
                  <Input
                    name="workspaceName"
                    value={value.workspaceName}
                    maxLength={100}
                    disabled={saving}
                    onChange={(event) => {
                      const workspaceName = event.target.value;
                      const automatic =
                        !value.workspaceSlug ||
                        value.workspaceSlug === slugFor(value.workspaceName);
                      change({
                        workspaceName,
                        ...(automatic
                          ? { workspaceSlug: slugFor(workspaceName) }
                          : {}),
                      });
                    }}
                    placeholder={l(
                      "e.g. Product team",
                      "p. ej. Equipo de producto",
                    )}
                  />
                </Field>
                <Field
                  htmlFor={`${id}-slug`}
                  label={l("Workspace identifier", "Identificador del espacio")}
                  description={l(
                    "A short identifier using lowercase letters, numbers and hyphens.",
                    "Un identificador corto con letras minúsculas, números y guiones.",
                  )}
                  error={errors.workspaceSlug}
                >
                  <Input
                    name="workspaceSlug"
                    autoCapitalize="none"
                    autoCorrect="off"
                    spellCheck={false}
                    value={value.workspaceSlug}
                    maxLength={64}
                    disabled={saving}
                    onChange={(event) =>
                      change({ workspaceSlug: event.target.value })
                    }
                    placeholder="product-team"
                  />
                </Field>
              </div>
            )}
            {!value.completed && step === 2 && (
              <div className="grid gap-5">
                <p className="text-sm leading-6 text-muted-foreground">
                  {l(
                    "Queue invitations now or continue on your own. This preview does not send invitation emails.",
                    "Prepara invitaciones o continúa por tu cuenta. Esta vista previa no envía correos de invitación.",
                  )}
                </p>
                <div className="grid items-end gap-3 sm:grid-cols-[minmax(0,1fr)_minmax(0,160px)_auto]">
                  <Field
                    htmlFor={`${id}-email`}
                    label={l("Invitation email", "Correo de invitación")}
                    error={errors.invite}
                  >
                    <Input
                      name="invitationEmail"
                      type="email"
                      autoComplete="email"
                      value={email}
                      disabled={saving}
                      onChange={(event) => {
                        setEmail(event.target.value);
                        setErrors({});
                      }}
                      onKeyDown={(event) => {
                        if (event.key === "Enter") {
                          event.preventDefault();
                          addInvite();
                        }
                      }}
                      placeholder="name@example.com"
                    />
                  </Field>
                  <Field htmlFor={`${id}-invite-role`} label={l("Role", "Rol")}>
                    <Select
                      options={roles}
                      value={role}
                      disabled={saving}
                      onValueChange={(next) => {
                        if (inviteRole(next)) setRole(next);
                      }}
                    />
                  </Field>
                  <Button
                    type="button"
                    variant="outline"
                    disabled={saving || !email.trim()}
                    onClick={addInvite}
                  >
                    <Plus aria-hidden="true" />
                    {l("Add", "Añadir")}
                  </Button>
                </div>
                {!!value.invites.length && (
                  <ul
                    className="grid gap-2"
                    aria-label={l(
                      "Queued invitations",
                      "Invitaciones preparadas",
                    )}
                  >
                    {value.invites.map((item, index) => (
                      <li
                        key={`${item.email}-${index}`}
                        className="flex min-w-0 flex-wrap items-center gap-3 rounded-lg border border-border bg-surface-subtle p-3"
                      >
                        <span className="min-w-0 flex-1 break-all text-sm">
                          {item.email}
                        </span>
                        <Badge variant="outline">
                          {roles.find((option) => option.value === item.role)
                            ?.label ?? item.role}
                        </Badge>
                        <Button
                          type="button"
                          size="icon-sm"
                          variant="ghost"
                          disabled={saving}
                          aria-label={`${l("Remove invitation for", "Quitar invitación de")} ${item.email}`}
                          onClick={() =>
                            change({
                              invites: value.invites.filter(
                                (_, position) => position !== index,
                              ),
                            })
                          }
                        >
                          <X aria-hidden="true" />
                        </Button>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            )}
            {(step === 3 || value.completed) && (
              <div className="grid gap-5">
                <dl className="grid gap-4 rounded-xl border border-border bg-surface-subtle p-4 sm:grid-cols-3">
                  {[
                    [l("Organization", "Organización"), value.organizationName],
                    [l("Workspace", "Espacio"), value.workspaceName],
                    [
                      l("Invitations queued", "Invitaciones preparadas"),
                      String(value.invites.length),
                    ],
                  ].map(([label, detail]) => (
                    <div key={label} className="min-w-0">
                      <dt className="text-xs text-muted-foreground">{label}</dt>
                      <dd className="mt-1 break-words text-sm font-semibold">
                        {detail}
                      </dd>
                    </div>
                  ))}
                </dl>
                <div className="grid gap-3 sm:grid-cols-2">
                  <Card className="flex flex-col gap-3 p-4">
                    <Database
                      aria-hidden="true"
                      className="size-5 text-primary"
                    />
                    <h3 className="text-sm font-semibold">
                      {l("Add a first customer", "Añade tu primer cliente")}
                    </h3>
                    <p className="flex-1 text-xs leading-6 text-muted-foreground">
                      {l(
                        "Start with one record and build your shared customer list.",
                        "Empieza con un registro y crea la lista compartida de clientes.",
                      )}
                    </p>
                    <Button
                      type="button"
                      variant="outline"
                      disabled={saving || !onOpenCustomers}
                      onClick={onOpenCustomers}
                    >
                      {l("Open customers", "Abrir clientes")}
                      <ArrowRight aria-hidden="true" />
                    </Button>
                  </Card>
                  <Card className="flex flex-col gap-3 p-4">
                    <Upload
                      aria-hidden="true"
                      className="size-5 text-primary"
                    />
                    <h3 className="text-sm font-semibold">
                      {l(
                        "Bring your existing data",
                        "Trae tus datos existentes",
                      )}
                    </h3>
                    <p className="flex-1 text-xs leading-6 text-muted-foreground">
                      {l(
                        "Review an import before adding existing records.",
                        "Revisa una importación antes de añadir registros existentes.",
                      )}
                    </p>
                    <Button
                      type="button"
                      variant="outline"
                      disabled={saving || !onOpenImports}
                      onClick={onOpenImports}
                    >
                      {l("Open imports", "Abrir importaciones")}
                      <ArrowRight aria-hidden="true" />
                    </Button>
                  </Card>
                </div>
                {!value.completed && (
                  <p className="text-xs leading-6 text-muted-foreground">
                    {l(
                      "You can finish setup now and add your first record later.",
                      "Puedes terminar la configuración y añadir tu primer registro después.",
                    )}
                  </p>
                )}
              </div>
            )}
            {failure && (
              <Alert
                variant="destructive"
                title={l(
                  "Setup needs another try",
                  "Hay que reintentar la configuración",
                )}
              >
                {failure}
              </Alert>
            )}
            {!value.completed && (
              <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border pt-5">
                <Button
                  type="button"
                  variant="ghost"
                  disabled={saving || step === 0}
                  onClick={() => change({ step: step - 1 })}
                >
                  <ArrowLeft aria-hidden="true" />
                  {l("Back", "Atrás")}
                </Button>
                <div className="flex flex-wrap items-center gap-2">
                  {step === 2 && !value.invites.length && (
                    <Button
                      type="button"
                      variant="ghost"
                      disabled={saving}
                      onClick={() => {
                        setEmail("");
                        change({ step: 3 });
                      }}
                    >
                      {l("Skip invitations", "Omitir invitaciones")}
                    </Button>
                  )}
                  <Button type="submit" appearance="gradient" loading={saving}>
                    {step === 3
                      ? l("Finish setup", "Terminar configuración")
                      : l("Continue", "Continuar")}
                    <ArrowRight aria-hidden="true" />
                  </Button>
                </div>
              </div>
            )}
          </form>
        </CardContent>
      </Card>
    </section>
  );
}

