"use client";
import { useLocale, useTranslations } from "next-intl";
import { useCallback } from "react";
import type { Locale } from "@/i18n/messages";
export function useLanguage() {
  const locale = useLocale() as Locale;
  const common = useTranslations("common");
  const l = useCallback(
    (en: string, es: string) => (locale === "es" ? es : en),
    [locale],
  );
  const number = useCallback(
    (value: number, options?: Intl.NumberFormatOptions) =>
      new Intl.NumberFormat(
        locale === "es" ? "es-CO" : "en-US",
        options,
      ).format(value),
    [locale],
  );
  const currency = useCallback(
    (value: number) =>
      number(value, {
        style: "currency",
        currency: "USD",
        maximumFractionDigits: 0,
      }),
    [number],
  );
  const date = useCallback(
    (value: Date | string, options?: Intl.DateTimeFormatOptions) =>
      new Intl.DateTimeFormat(
        locale === "es" ? "es-CO" : "en-US",
        options ?? { month: "short", day: "numeric", year: "numeric" },
      ).format(
        new Date(
          typeof value === "string" && value.length === 10
            ? `${value}T12:00:00`
            : value,
        ),
      ),
    [locale],
  );
  return { locale, common, l, number, currency, date };
}

import type {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnPinningState,
  ColumnSizingState,
  PaginationState,
  SortingState,
  VisibilityState,
} from "@tanstack/react-table";

/** Serializable table state. Filtering, sorting and pagination belong to the data owner in external mode. */
export type DataTableQuery = {
  search: string;
  filters: ColumnFiltersState;
  sorting: SortingState;
  pagination: PaginationState;
};

/** Separate from DataTable's existing `columnVisibility` menu flag. */
export type DataTableColumnState = {
  visibility: VisibilityState;
  order: ColumnOrderState;
  sizing: ColumnSizingState;
  pinning: ColumnPinningState;
};

export type DataFilterScalar = string | number | boolean | null;
export type DataFilter =
  | { operator: "contains" | "startsWith"; value: string }
  | { operator: "equals" | "notEquals"; value: DataFilterScalar }
  | { operator: "in" | "notIn"; value: DataFilterScalar[] }
  | { operator: "gt" | "gte" | "lt" | "lte"; value: number }
  | { operator: "between"; value: [number | null, number | null] }
  | { operator: "dateBetween"; value: [string | null, string | null] }
  | { operator: "isEmpty" | "isNotEmpty" };

type JsonValue = DataFilterScalar | JsonValue[] | { [key: string]: JsonValue };

export type DataQueryNormalizationOptions = {
  pageSize?: number;
  maxPageSize?: number;
  columnIds?: readonly string[];
};

function record(value: unknown): Record<string, unknown> | undefined {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    (Object.getPrototypeOf(value) !== Object.prototype &&
      Object.getPrototypeOf(value) !== null)
  ) {
    return undefined;
  }
  return value as Record<string, unknown>;
}

function jsonValue(value: unknown, depth = 0): JsonValue | undefined {
  if (depth > 12) return undefined;
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean"
  ) {
    return value;
  }
  if (typeof value === "number")
    return Number.isFinite(value) ? value : undefined;
  if (Array.isArray(value)) {
    const values = value.map((item) => jsonValue(item, depth + 1));
    return values.some((item) => item === undefined)
      ? undefined
      : (values as JsonValue[]);
  }
  const object = record(value);
  if (!object) return undefined;
  const entries = Object.keys(object)
    .sort()
    .map((key) => [key, jsonValue(object[key], depth + 1)] as const);
  return entries.some(([, item]) => item === undefined)
    ? undefined
    : (Object.fromEntries(entries) as { [key: string]: JsonValue });
}

function integer(
  value: unknown,
  fallback: number,
  minimum: number,
  maximum = Number.MAX_SAFE_INTEGER,
) {
  const number =
    typeof value === "number"
      ? value
      : typeof value === "string" && value.trim()
        ? Number(value)
        : NaN;
  return Number.isFinite(number)
    ? Math.min(maximum, Math.max(minimum, Math.trunc(number)))
    : fallback;
}

function scalar(value: unknown): value is DataFilterScalar {
  return (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  );
}

function dateDay(value: unknown): number | undefined {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value))
    return undefined;
  const timestamp = Date.parse(`${value}T00:00:00.000Z`);
  return Number.isFinite(timestamp) &&
    new Date(timestamp).toISOString().slice(0, 10) === value
    ? timestamp
    : undefined;
}

export function isDataFilter(value: unknown): value is DataFilter {
  const filter = record(value);
  if (!filter) return false;
  switch (filter.operator) {
    case "contains":
    case "startsWith":
      return typeof filter.value === "string";
    case "equals":
    case "notEquals":
      return scalar(filter.value);
    case "in":
    case "notIn":
      return Array.isArray(filter.value) && filter.value.every(scalar);
    case "gt":
    case "gte":
    case "lt":
    case "lte":
      return typeof filter.value === "number" && Number.isFinite(filter.value);
    case "between":
      return (
        Array.isArray(filter.value) &&
        filter.value.length === 2 &&
        filter.value.every(
          (bound) =>
            bound === null ||
            (typeof bound === "number" && Number.isFinite(bound)),
        )
      );
    case "dateBetween":
      return (
        Array.isArray(filter.value) &&
        filter.value.length === 2 &&
        filter.value.every(
          (bound) => bound === null || dateDay(bound) !== undefined,
        )
      );
    case "isEmpty":
    case "isNotEmpty":
      return true;
    default:
      return false;
  }
}

function emptyFilter(value: unknown) {
  if (value === undefined || value === "") return true;
  if (!isDataFilter(value)) return Array.isArray(value) && value.length === 0;
  if (value.operator === "contains" || value.operator === "startsWith")
    return value.value === "";
  if (value.operator === "in" || value.operator === "notIn")
    return value.value.length === 0;
  if (value.operator === "between" || value.operator === "dateBetween") {
    return value.value.every((bound) => bound === null);
  }
  return false;
}

export function normalizeDataTableQuery(
  value: unknown = {},
  options: DataQueryNormalizationOptions = {},
): DataTableQuery {
  const input = record(value) ?? {};
  const allowed = options.columnIds ? new Set(options.columnIds) : undefined;
  const id = (value: unknown) =>
    typeof value === "string" &&
    value.trim() &&
    (!allowed || allowed.has(value))
      ? value
      : undefined;
  const filters = new Map<string, JsonValue>();
  for (const item of Array.isArray(input.filters) ? input.filters : []) {
    const filter = record(item),
      columnId = id(filter?.id);
    if (!filter || !columnId) continue;
    const normalized = jsonValue(filter.value);
    if (
      emptyFilter(normalized) ||
      (record(normalized)?.operator !== undefined && !isDataFilter(normalized))
    ) {
      filters.delete(columnId);
    } else if (normalized !== undefined) {
      filters.set(columnId, normalized);
    }
  }
  const sorting = new Map<string, { id: string; desc: boolean }>();
  for (const item of Array.isArray(input.sorting) ? input.sorting : []) {
    const sort = record(item),
      columnId = id(sort?.id);
    if (columnId)
      sorting.set(columnId, { id: columnId, desc: sort?.desc === true });
  }
  const pagination = record(input.pagination) ?? {};
  const maximum = integer(options.maxPageSize, Number.MAX_SAFE_INTEGER, 1);
  const fallbackSize = integer(options.pageSize, 5, 1, maximum);
  return {
    // Preserve spaces while typing. Trimming controlled input state loses word separators.
    search: typeof input.search === "string" ? input.search : "",
    filters: [...filters]
      .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
      .map(([id, value]) => ({ id, value })),
    // Multi-sort precedence is ordered, unlike AND filters.
    sorting: [...sorting.values()],
    pagination: {
      pageIndex: integer(pagination.pageIndex, 0, 0),
      pageSize: integer(pagination.pageSize, fallbackSize, 1, maximum),
    },
  };
}

export function serializeDataTableQuery(query: DataTableQuery): string {
  return JSON.stringify({ version: 1, query: normalizeDataTableQuery(query) });
}

export function parseDataTableQuery(
  source: string | null | undefined,
  options: DataQueryNormalizationOptions = {},
): DataTableQuery {
  if (!source) return normalizeDataTableQuery({}, options);
  try {
    const input = record(JSON.parse(source));
    return input?.version === 1
      ? normalizeDataTableQuery(input.query, options)
      : normalizeDataTableQuery({}, options);
  } catch {
    return normalizeDataTableQuery({}, options);
  }
}

export function normalizeDataTableColumnState(
  value: Partial<DataTableColumnState> | unknown = {},
): DataTableColumnState {
  const input = record(value) ?? {};
  const visibility = record(input.visibility) ?? {},
    sizing = record(input.sizing) ?? {};
  const ids = (value: unknown) => [
    ...new Set(
      (Array.isArray(value) ? value : []).filter(
        (id): id is string => typeof id === "string" && id.trim().length > 0,
      ),
    ),
  ];
  const pinning = record(input.pinning) ?? {},
    left = ids(pinning.left);
  return {
    visibility: Object.fromEntries(
      Object.entries(visibility)
        .filter(([, visible]) => typeof visible === "boolean")
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    ) as VisibilityState,
    order: ids(input.order),
    sizing: Object.fromEntries(
      Object.entries(sizing)
        .filter(
          ([, size]) =>
            typeof size === "number" && Number.isFinite(size) && size > 0,
        )
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    ) as ColumnSizingState,
    pinning: {
      left,
      right: ids(pinning.right).filter((id) => !left.includes(id)),
    },
  };
}

function fold(value: unknown) {
  return String(value ?? "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function numeric(value: unknown): number | undefined {
  if (typeof value === "number")
    return Number.isFinite(value) ? value : undefined;
  if (typeof value !== "string" || !value.trim()) return undefined;
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

/** AND across columns; `in` is OR within one field. No implicit conversion of empty cells to zero. */
export function matchesDataFilter(value: unknown, filter: unknown): boolean {
  if (emptyFilter(filter)) return true;
  if (!isDataFilter(filter)) {
    if (Array.isArray(filter))
      return filter.some((item) => Object.is(item, value));
    return typeof filter === "string"
      ? fold(value).includes(fold(filter))
      : Object.is(value, filter);
  }
  switch (filter.operator) {
    case "contains":
      return fold(value).includes(fold(filter.value));
    case "startsWith":
      return fold(value).startsWith(fold(filter.value));
    case "equals":
      return Object.is(value, filter.value);
    case "notEquals":
      return !Object.is(value, filter.value);
    case "in":
      return filter.value.some((item) => Object.is(item, value));
    case "notIn":
      return !filter.value.some((item) => Object.is(item, value));
    case "isEmpty":
      return (
        value === null ||
        value === undefined ||
        value === "" ||
        (Array.isArray(value) && value.length === 0)
      );
    case "isNotEmpty":
      return (
        value !== null &&
        value !== undefined &&
        value !== "" &&
        (!Array.isArray(value) || value.length > 0)
      );
    case "dateBetween": {
      const timestamp =
        value instanceof Date
          ? value.getTime()
          : typeof value === "string"
            ? value.length === 10
              ? (dateDay(value) ?? NaN)
              : Date.parse(value)
            : NaN;
      const [from, to] = filter.value;
      return (
        Number.isFinite(timestamp) &&
        (from === null || timestamp >= dateDay(from)!) &&
        (to === null || timestamp < dateDay(to)! + 86_400_000)
      );
    }
    default: {
      const number = numeric(value);
      if (number === undefined) return false;
      if (filter.operator === "between") {
        const [from, to] = filter.value;
        return (
          (from === null || number >= from) && (to === null || number <= to)
        );
      }
      if (filter.operator === "gt") return number > filter.value;
      if (filter.operator === "gte") return number >= filter.value;
      if (filter.operator === "lt") return number < filter.value;
      return number <= filter.value;
    }
  }
}

export function filterDataRows<T>(
  rows: readonly T[],
  filters: ColumnFiltersState,
  getValue: (row: T, columnId: string) => unknown,
): T[] {
  return rows.filter((row) =>
    filters.every((filter) =>
      matchesDataFilter(getValue(row, filter.id), filter.value),
    ),
  );
}

/**
 * Add the build's mount point to a public asset or native HTML link.
 * Keep next/link and Next's router paths unprefixed: Next handles those itself.
 */
export function publicPath(
  path: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "",
): string {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  const prefix = basePath.trim().replace(/^\/+|\/+$/g, "");
  if (!prefix) return path;
  const base = `/${prefix}`;
  if (
    path === base ||
    path.startsWith(`${base}/`) ||
    path.startsWith(`${base}?`) ||
    path.startsWith(`${base}#`)
  ) {
    return path;
  }
  return `${base}${path}`;
}

import { z } from "zod";
import type { Customer } from "../demo/dashboard-data";

export type WorkspaceRole = "owner" | "admin" | "member" | "viewer";
export type InviteRole = Exclude<WorkspaceRole, "owner">;
export type WorkspaceCapability =
  | "workspace.manage"
  | "members.manage"
  | "ownership.transfer"
  | "customers.write"
  | "customers.import"
  | "notes.write"
  | "views.manage";

export type Workspace = {
  id: string;
  organizationName: string;
  name: string;
  slug: string;
  description: string;
};
export type WorkspaceMember = {
  id: string;
  name: string;
  email: string;
  role: WorkspaceRole;
  status: "active" | "suspended";
  joinedAt: string;
};
export type WorkspaceInvitation = {
  id: string;
  email: string;
  role: InviteRole;
  status: "pending" | "accepted" | "expired" | "revoked";
  expiresAt: string;
};
export type CustomerNote = {
  id: string;
  text: string;
  author: string;
  authorMemberId?: string;
  createdAt: string;
};
export type CustomerAttachment = {
  id: string;
  name: string;
  size: number;
  type: string;
  createdAt: string;
};
export type WorkspaceActivity = {
  id: string;
  actor: string;
  detail: string;
  occurredAt: string;
  resourceId?: string;
  kind: "workspace" | "member" | "customer" | "import" | "note" | "view";
};
export type OnboardingDraft = {
  step: number;
  organizationName: string;
  workspaceName: string;
  workspaceSlug: string;
  invites: { email: string; role: InviteRole }[];
  completed: boolean;
  workspaceId?: string;
};
export type SavedWorkspaceView = {
  id: string;
  name: string;
  value: unknown;
};
export type WorkspaceData = {
  customers: Customer[];
  members: WorkspaceMember[];
  invitations: WorkspaceInvitation[];
  notes: Record<string, CustomerNote[]>;
  activity: WorkspaceActivity[];
  savedViews: SavedWorkspaceView[];
  customerView?: unknown;
  files?: Record<string, CustomerAttachment[]>;
};
export type SaasDemoState = {
  version: 1;
  activeWorkspaceId: string;
  currentMemberId: string;
  workspaces: Workspace[];
  data: Record<string, WorkspaceData>;
  onboarding: OnboardingDraft;
  previewRole?: WorkspaceRole;
};

export const SAAS_STORAGE_KEY = "aureform:saas:v1";
const allCapabilities: WorkspaceCapability[] = [
  "workspace.manage",
  "members.manage",
  "ownership.transfer",
  "customers.write",
  "customers.import",
  "notes.write",
  "views.manage",
];
const roleCapabilities: Record<WorkspaceRole, readonly WorkspaceCapability[]> =
  {
    owner: allCapabilities,
    admin: allCapabilities.filter((item) => item !== "ownership.transfer"),
    member: [
      "customers.write",
      "customers.import",
      "notes.write",
      "views.manage",
    ],
    viewer: [],
  };
export function hasCapability(
  role: WorkspaceRole,
  capability: WorkspaceCapability,
): boolean {
  return roleCapabilities[role].includes(capability);
}
export function workspaceSlug(name: string): string {
  return name
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 64)
    .replace(/-+$/g, "");
}
export type SaasErrorCode =
  "permission" | "invalid" | "duplicate" | "owner" | "expired" | "missing";
export class SaasError extends Error {
  readonly code: SaasErrorCode;
  constructor(code: SaasErrorCode) {
    super(code);
    this.name = "SaasError";
    this.code = code;
  }
}

const roleSchema = z.enum(["owner", "admin", "member", "viewer"]);
const inviteRoleSchema = z.enum(["admin", "member", "viewer"]);
export const workspaceInputSchema = z.object({
  organizationName: z.string().trim().min(2).max(100),
  name: z.string().trim().min(2).max(100),
  slug: z
    .string()
    .trim()
    .min(2)
    .max(64)
    .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  description: z.string().trim().max(500),
});
export const customerSchema = z.object({
  id: z.string().min(1).max(128),
  name: z.string().trim().min(2).max(120),
  email: z.email().max(254),
  company: z.string().max(200),
  plan: z.string().max(60),
  status: z.string().max(60),
  amount: z.number().finite().nonnegative(),
  joined: z.iso.date(),
});
const memberSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  email: z.email(),
  role: roleSchema,
  status: z.enum(["active", "suspended"]),
  joinedAt: z.string(),
});
const invitationSchema = z.object({
  id: z.string().min(1),
  email: z.email(),
  role: inviteRoleSchema,
  status: z.enum(["pending", "accepted", "expired", "revoked"]),
  expiresAt: z.iso.datetime(),
});
const noteSchema = z.object({
  id: z.string(),
  text: z.string().min(1).max(10000),
  author: z.string(),
  authorMemberId: z.string().min(1).optional(),
  createdAt: z.iso.datetime(),
});
const activitySchema = z.object({
  id: z.string(),
  actor: z.string(),
  detail: z.string(),
  occurredAt: z.iso.datetime(),
  resourceId: z.string().optional(),
  kind: z.enum(["workspace", "member", "customer", "import", "note", "view"]),
});
const dataSchema = z.object({
  customers: z.array(customerSchema).max(25000),
  members: z.array(memberSchema).min(1).max(1000),
  invitations: z.array(invitationSchema).max(1000),
  notes: z.record(z.string(), z.array(noteSchema).max(1000)),
  activity: z.array(activitySchema).max(2000),
  savedViews: z
    .array(
      z.object({
        id: z.string().min(1),
        name: z.string().min(1).max(80),
        value: z.unknown(),
      }),
    )
    .max(100),
  customerView: z.unknown().optional(),
  files: z
    .record(
      z.string(),
      z
        .array(
          z.object({
            id: z.string().min(1),
            name: z.string().min(1).max(255),
            size: z
              .number()
              .int()
              .nonnegative()
              .max(10 * 1024 * 1024),
            type: z.string().max(255),
            createdAt: z.iso.datetime(),
          }),
        )
        .max(100),
    )
    .optional(),
});
const stateSchema = z.object({
  version: z.literal(1),
  activeWorkspaceId: z.string(),
  currentMemberId: z.string().min(1),
  previewRole: roleSchema.optional(),
  workspaces: z
    .array(workspaceInputSchema.extend({ id: z.string().min(1) }))
    .min(1)
    .max(100),
  data: z.record(z.string(), dataSchema),
  onboarding: z.object({
    step: z.number().int().min(0).max(3),
    organizationName: z.string().max(100),
    workspaceName: z.string().max(100),
    workspaceSlug: z.string().max(64),
    invites: z
      .array(z.object({ email: z.string().max(254), role: inviteRoleSchema }))
      .max(50),
    completed: z.boolean(),
    workspaceId: z.string().optional(),
  }),
});

/** Untrusted browser persistence is checked before it reaches any UI. */
export function parseSaasState(value: unknown): SaasDemoState | null {
  const parsed = stateSchema.safeParse(value);
  if (!parsed.success) return null;
  const state = parsed.data as SaasDemoState;
  const ids = state.workspaces.map((item) => item.id);
  if (
    new Set(ids).size !== ids.length ||
    !ids.includes(state.activeWorkspaceId)
  )
    return null;
  const slugs = state.workspaces.map((item) => item.slug);
  if (new Set(slugs).size !== slugs.length) return null;
  for (const id of ids) {
    if (!Object.hasOwn(state.data, id)) return null;
    const data = state.data[id];
    if (
      data.members.filter((member) => member.role === "owner").length !== 1 ||
      !data.members.some(
        (member) => member.role === "owner" && member.status === "active",
      )
    )
      return null;
    if (
      !data.members.some(
        (member) =>
          member.id === state.currentMemberId && member.status === "active",
      )
    )
      return null;
    if (
      new Set(data.customers.map((item) => item.id)).size !==
      data.customers.length
    )
      return null;
    if (
      new Set(data.members.map((item) => item.id)).size !== data.members.length
    )
      return null;
    if (
      new Set(data.members.map((item) => item.email.toLowerCase())).size !==
      data.members.length
    )
      return null;
  }
  return state;
}

export function updateWorkspaceData(
  state: SaasDemoState,
  id: string,
  updater: (previous: WorkspaceData) => WorkspaceData,
): SaasDemoState {
  if (!Object.hasOwn(state.data, id)) throw new SaasError("missing");
  return { ...state, data: { ...state.data, [id]: updater(state.data[id]) } };
}
export function transferWorkspaceOwnership(
  members: WorkspaceMember[],
  actorId: string,
  targetId: string,
): WorkspaceMember[] {
  const actor = members.find((item) => item.id === actorId);
  const target = members.find((item) => item.id === targetId);
  if (actor?.role !== "owner" || actor.status !== "active")
    throw new SaasError("permission");
  if (!target || target.status !== "active" || actorId === targetId)
    throw new SaasError("invalid");
  return members.map((item) =>
    item.id === actorId
      ? { ...item, role: "admin" }
      : item.id === targetId
        ? { ...item, role: "owner" }
        : item,
  );
}
export function changeWorkspaceMemberRole(
  members: WorkspaceMember[],
  targetId: string,
  role: WorkspaceRole,
  actorId?: string,
): WorkspaceMember[] {
  const target = members.find((item) => item.id === targetId);
  if (!target) throw new SaasError("missing");
  if (target.role === "owner" || role === "owner" || targetId === actorId)
    throw new SaasError("owner");
  return members.map((item) =>
    item.id === targetId ? { ...item, role } : item,
  );
}
export function removeWorkspaceMember(
  members: WorkspaceMember[],
  actorId: string,
  targetId: string,
): WorkspaceMember[] {
  const target = members.find((item) => item.id === targetId);
  if (!target) throw new SaasError("missing");
  if (target.role === "owner" || targetId === actorId)
    throw new SaasError("owner");
  return members.filter((item) => item.id !== targetId);
}

export type CustomerImportResult = {
  created: number;
  updated: number;
  skipped: number;
  failed: number;
};
/** Transactional merge; callers commit the result only after cancellation checks. */
export function mergeImportedCustomers(
  existing: Customer[],
  imported: Customer[],
  mode: "skip" | "update",
): { customers: Customer[]; result: CustomerImportResult } {
  const customers = existing.map((item) => ({ ...item }));
  const indices = new Map(
    customers.map((item, index) => [item.email.trim().toLowerCase(), index]),
  );
  const result: CustomerImportResult = {
    created: 0,
    updated: 0,
    skipped: 0,
    failed: 0,
  };
  for (const candidate of imported) {
    const parsed = customerSchema.safeParse(candidate);
    if (!parsed.success) {
      result.failed++;
      continue;
    }
    const customer = parsed.data;
    const email = customer.email.trim().toLowerCase();
    const index = indices.get(email);
    if (index !== undefined) {
      if (mode === "skip") {
        result.skipped++;
      } else {
        customers[index] = { ...customer, id: customers[index].id };
        result.updated++;
      }
    } else {
      if (customers.some((item) => item.id === customer.id)) {
        result.failed++;
        continue;
      }
      indices.set(email, customers.length);
      customers.push(customer);
      result.created++;
    }
  }
  return { customers, result };
}

import {
  normalizeDataTableColumnState,
  normalizeDataTableQuery,
  type DataTableColumnState,
  type DataTableQuery,
} from "./data-query";

export type DataView = {
  query: DataTableQuery;
  columns: DataTableColumnState;
  density: "comfortable" | "compact";
};

/** URL and browser storage are inputs, never trusted table state. */
export function normalizeDataView(value: unknown, columnIds: readonly string[]): DataView {
  const input = value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const columns = normalizeDataTableColumnState(input.columns);
  const allowed = new Set([...columnIds, "select", "actions"]);
  return {
    query: normalizeDataTableQuery(input.query, { columnIds, pageSize: 5, maxPageSize: 100 }),
    columns: {
      visibility: Object.fromEntries(Object.entries(columns.visibility).filter(([id]) => allowed.has(id))),
      order: columns.order.filter((id) => allowed.has(id)),
      sizing: Object.fromEntries(Object.entries(columns.sizing).filter(([id]) => allowed.has(id))),
      pinning: {
        left: columns.pinning.left?.filter((id) => allowed.has(id)),
        right: columns.pinning.right?.filter((id) => allowed.has(id)),
      },
    },
    density: input.density === "compact" ? "compact" : "comfortable",
  };
}

export function serializeDataView(value: unknown, columnIds: readonly string[]): string {
  return JSON.stringify({ version: 1, value: normalizeDataView(value, columnIds) });
}

export function parseDataView(source: string | null | undefined, columnIds: readonly string[]): DataView | null {
  if (!source || source.length > 12000) return null;
  try {
    const input = JSON.parse(source);
    if (!input || input.version !== 1 || !input.value || typeof input.value !== "object") return null;
    return normalizeDataView(input.value, columnIds);
  } catch {
    return null;
  }
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

/*
 * Aureform effects. Import after the generated tokens.css in globals.css.
 * Component-layer rules allow Tailwind utilities to override decoration.
 * Shadow composition retains Tailwind 4 focus rings.
 */
@layer components {
  .af-surface-gradient {
    background-color: var(--surface);
    background-image: var(--af-gradient-surface);
  }

  .af-hero-gradient {
    background-color: var(--background);
    background-image: var(--af-gradient-hero);
  }

  .af-shadow-soft {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-shadow-elevated {
    --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
  }

  .af-shadow-floating {
    --tw-shadow: var(--af-shadow-floating);
  }

  .af-shadow-soft,
  .af-shadow-elevated,
  .af-shadow-floating,
  .af-hover-card,
  .af-button {
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000);
  }

  .af-button {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-button-primary,
  .af-button-outline,
  .af-button-surface,
  .af-button-destructive {
    background-image: var(--af-gradient-control);
  }

  .af-button-primary,
  .af-button-surface,
  .af-button-destructive {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-hover-card {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      transform var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-hover-link {
    color: var(--primary);
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--primary) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.22em;
    transition:
      color var(--af-motion-fast) var(--af-motion-easing),
      text-decoration-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-hover-link:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    color: var(--primary-hover);
    text-decoration-color: currentColor;
    text-decoration-thickness: 2px;
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  @media (hover: hover) and (pointer: fine) {
    .af-button-outline:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-shadow-soft);
    }

    .af-hover-link:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      color: var(--primary-hover);
      text-decoration-color: currentColor;
      text-decoration-thickness: 2px;
    }
  }

  .af-button:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):active {
    --tw-shadow: 0 0 #0000;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    cursor: default;
    pointer-events: none;
    animation: none;
    transition: none;
    transform: none;
    translate: none;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    --tw-shadow: 0 0 #0000;
    background-image: none;
  }
}

